void DapnetClient::disconnect()
{
    client.stop();

    tcpConnected = false;
    loggedIn     = false;

    Serial.println("DAPNET disconnected.");
}

DapnetMessage DapnetClient::getMessage()
{
    DapnetMessage msg;

    dequeueMessage(msg);

    return msg;

}

bool DapnetClient::enqueueMessage(const DapnetMessage& msg)
{
    // Full? Discard oldest entry
    if( queueCount >= DAPNET_QUEUE_SIZE )
    {
        queueTail = queueTail + 1;

        if( queueTail >= DAPNET_QUEUE_SIZE )
        {
            queueTail = 0;
        }

        queueCount = queueCount - 1;
    }

    queue[queueHead] = msg;
    queueHead = queueHead + 1;

    if( queueHead >= DAPNET_QUEUE_SIZE )
    {
        queueHead = 0;
    }

    queueCount = queueCount + 1;

    return true;
    
}

bool DapnetClient::dequeueMessage(DapnetMessage& msg)
{
    if( queueCount == 0 )
    {
        return false;
    }

    msg = queue[queueTail];
    queueTail = queueTail + 1;

    if( queueTail >= DAPNET_QUEUE_SIZE )
    {
        queueTail = 0;
    }

    queueCount = queueCount - 1;

    return true;
    
}

void DapnetClient::sendLine(const String& line)
{
    client.print(line);
    client.print("\n");

    Serial.print("DAPNET TX: "); Serial.println(line);
}

String DapnetClient::readLine()
{
    String   line;
    uint32_t start = millis();

    while( client.connected() )
    {
        while( client.available() )
        {
            char c = client.read();

            if( c == '\n' )
            {
                line.trim();

                return line;
            }

            line += c;
        }

        if( millis() - start > DAPNET_SOCKET_TIMEOUT )
        {
            break;
        }

        delay(1);
    }

    return "";
    
}

bool DapnetClient::connectServer()
{
    Serial.println();
    Serial.println("Connecting to DAPNET...");

    client.stop();

    if( !client.connect(host.c_str(), port) )
    {
        Serial.println("TCP connect failed.");

        return false;
    }

    tcpConnected = true;

    Serial.println("TCP connect successful.");

    return true;

}

void DapnetClient::acknowledge(uint8_t counter)
{
    char ack[16];

    sprintf(ack, "#%02X +", (counter + 1) & 0xff);

    sendLine(ack);

}

bool DapnetClient::login()
{
    String loginString = "[CYD-DAPNET-Monitor v1.0 " + callsign + " " + authkey + "]";

    sendLine(loginString);

    for( int i = 0; i < 5; i++ )
    {
        String line = readLine();

        Serial.print("DAPNET RX: "); Serial.println(line);

        if( !line.startsWith("2:") )
        {
            return false;
        }

        sendLine( line + ":0000");
        sendLine("+");
    }

    String line = readLine();

    Serial.print("DAPNET RX: "); Serial.println(line);

    if( line.startsWith("3:") )
    {
        sendLine("+");

        line = readLine();
    }

    if( !line.startsWith("4:") )
    {
        return false;
    }

    timeslots = line.substring(line.indexOf(':') + 1);
    sendLine("+");

    loggedIn = true;

    Serial.print("Timeslots = "); Serial.println(timeslots);
    Serial.println("Connected to DAPNET. Logged in.");

    return true;

}

bool DapnetClient::decodePayload(const String& payload, DapnetMessage& msg)
{
    msg     = DapnetMessage();
    msg.raw = payload;
    int p1  =  payload.indexOf(':');

    if( p1 < 0 )
        return false;

    msg.type = payload.substring(0, p1).toInt();

    // Type 6
    if(msg.type == 6)
    {
        int p2 = payload.indexOf(':', p1 + 1);
        int p3 = payload.indexOf(':', p2 + 1);
        int p4 = payload.indexOf(':', p3 + 1);

        if( p2 < 0 || p3 < 0 || p4 < 0 )
        {
            return false;
        }

        msg.baud = payload.substring(p1 + 1, p2).toInt();

        String ricHex = payload.substring(p2 + 1, p3);

        msg.ric = strtoul(ricHex.c_str(), nullptr, 16);
        msg.function = payload.substring(p3 + 1, p4).toInt();
        msg.text = payload.substring(p4 + 1);
    }

    msg.valid = true;

    return true;
    
}

bool DapnetClient::processLine(const String& line)
{
    if( !line.startsWith("#") )
    {
        return false;
    }

    int separator = line.indexOf(' ');

    if( separator < 0 )
    {
        return false;
    }

    String counterString = line.substring( 1, separator );
    uint8_t counter = strtoul(counterString.c_str(), nullptr, 16);
    String payload = line.substring(separator + 1);

    acknowledge(counter);

    DapnetMessage msg;

    if( decodePayload(payload, msg) )
    {
        enqueueMessage(msg);

        Serial.print("QUEUE: "); Serial.print(queueCount);
        Serial.print(" RIC: ");  Serial.print(msg.ric);
        Serial.print(" FUNC: "); Serial.print(msg.function);
        Serial.print(" TEXT: "); Serial.println(msg.text);
    }

    return true;
    
}

void DapnetClient::reconnect()
{
    if( millis() - reconnectTimer < DAPNET_RECONNECT_INTERVAL )
    {
        return;
    }

    reconnectTimer = millis();
    disconnect();

    if( !connectServer() )
    {
        return;
    }

    if( !login() )
    {
        disconnect();
        return;
    }

    Serial.println("DAPNET online.");
    
}


void DapnetClient::loop()
{
    if( !WiFi.isConnected() )
    {
        loggedIn = false;
        return;
    }

    if( !client.connected() )
    {
        loggedIn = false;
        reconnect();

        return;
    }

    while( client.available() )
    {
        String line = client.readStringUntil('\n');

        line.trim();

        if( line.isEmpty() )
        {
            continue;
        }

        Serial.print("DAPNET RX: "); Serial.println(line);

        processLine(line);
    }

}
